#include <cassert>
#include <iostream>
#include "service/user_service.h"
#include "service/transaction_manager.h"
#include "db/database_client.h"
#include "model/transaction.h"

int main() {
    db::DatabaseClient db;
    service::TransactionManager tx_manager(db);
    service::UserService user_service(tx_manager);

    model::Transaction tx;
    tx.id = "tx_789";
    tx.amount = 150.0;

    // Run transaction as dry_run = true
    user_service.process_transaction("usr_123", tx, true);

    // Verify dry_run is true
    if (!db.last_tx_dry_run_) {
        std::cerr << "FAIL: dry_run flag not propagated to DB" << std::endl;
        return 1;
    }

    // Verify it was NOT committed
    for (const auto& id : db.committed_tx_ids_) {
        if (id == "tx_789") {
            std::cerr << "FAIL: Dry run transaction committed to DB" << std::endl;
            return 1;
        }
    }

    std::cout << "SUCCESS" << std::endl;
    return 0;
}

#!/usr/bin/env python3
import sys
import subprocess
from pathlib import Path

def main():
    order_cpp = Path("src/service/order_service.cpp")
    if not order_cpp.exists():
        print(f"FAIL: {order_cpp} not found")
        sys.exit(1)

    cpp_files = [
        "src/service/order_service.cpp",
        "src/service/inventory_client.cpp"
    ]

    # Compile check
    cmd = ["clang++", "-std=c++17", "-Isrc"] + cpp_files + ["test_003.cpp", "-o", "test_003"]
    res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0:
        print("FAIL: Compilation error")
        print(res.stderr)
        sys.exit(1)

    # Run check
    try:
        run_res = subprocess.run(["./test_003"], capture_output=True, text=True, timeout=5)
        if run_res.returncode != 0:
            print("FAIL: Test execution failed")
            print(run_res.stdout)
            print(run_res.stderr)
            sys.exit(1)
        if "SUCCESS" not in run_res.stdout:
            print("FAIL: Execution output mismatch")
            sys.exit(1)
    finally:
        # cleanup
        for p in [Path("test_003"), Path("test_003.exe")]:
            if p.exists():
                try:
                    p.unlink()
                except:
                    pass

    print("OK")

if __name__ == "__main__":
    main()
